#!/usr/bin/env node
// PreToolUse guard: refuse Edit/Write on generated JS output.
// These are compiled from TS sources — see the feedback-ts-only memory.
let input = '';
process.stdin.on('data', (d) => { input += d; });
process.stdin.on('end', () => {
  let filePath;
  try {
    filePath = JSON.parse(input).tool_input?.file_path;
  } catch {
    process.exit(0);
  }
  if (!filePath) process.exit(0);
  const norm = filePath.replace(/\\/g, '/');

  let reason = null;
  if (/\/extensions\/[^/]+\/out\/[^/]+\.js$/.test(norm)) {
    reason =
      'This is compiled output (out/*.js) regenerated by tsc — manual edits get overwritten. Edit the TypeScript source in the matching src/ directory instead.';
  } else if (/\/extensions\/null-tools\/lib\/agents\.js$/.test(norm)) {
    reason =
      'lib/agents.js is compiled from src/webview/agents.ts. Edit that TypeScript source instead — manual edits to lib/agents.js get overwritten on rebuild.';
  }

  if (reason) {
    console.log(
      JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'deny',
          permissionDecisionReason: reason,
        },
      })
    );
  }
  process.exit(0);
});
